def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_ivs = sorted([list(iv) for iv in intervals], key=lambda x: x[0])
    merged = []
    for start, end in sorted_ivs:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)

    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for src, dst in unique_edges:
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("each weight must be positive and not exceed limit")

    if not items:
        return []

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight

    if current_batch:
        batches.append(current_batch)

    return batches

import re

def parse_env(text):
    env = {}
    key_pat = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_pat.match(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2:
            if (value.startswith("'") and value.endswith("'")) or \
               (value.startswith('"') and value.endswith('"')):
                value = value[1:-1]
        env[key] = value
    return env

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    # base > 0 and cap > 0
    # Compare using logarithms to avoid overflow/huge integers
    # base * 2**attempt >= cap  <=>  attempt >= log2(cap) - log2(base)
    threshold = math.log2(cap) - math.log2(base)
    if attempt >= threshold:
        return float(cap)
    else:
        # The result is strictly less than cap and representable as float
        return math.ldexp(base, attempt)

def fifo_admit(active, queued, budget, slots):
    if any(r > budget for r in queued):
        raise ValueError("queued reservation exceeds budget")
    admitted = []
    cur_tokens = sum(active)
    cur_slots = len(active)
    idx = 0
    while idx < len(queued):
        tokens = queued[idx]
        if cur_tokens + tokens <= budget and cur_slots + 1 <= slots:
            admitted.append(tokens)
            cur_tokens += tokens
            cur_slots += 1
            idx += 1
        else:
            break
    remaining = queued[idx:]
    return (admitted, remaining)
